// ノイズ関数
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

// 2Dノイズ
float noise(vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 座標の正規化
    vec2 uv = fragCoord/iResolution.xy;

    // 時間パラメータ
    float time = iTime * 0.3;

    // 波の動きの生成（複数のノイズを重ねる）
    float wave1 = noise(vec2(uv.x * 3.0 + time * 0.5, uv.y * 3.0));
    float wave2 = noise(vec2(uv.x * 5.0 - time * 0.3, uv.y * 5.0));
    float wave3 = noise(vec2(uv.x * 8.0 + time * 0.4, uv.y * 8.0));

    // 波を合成
    float waves = (wave1 * 0.5 + wave2 * 0.3 + wave3 * 0.2) * 0.8;

    // 深い青から明るい青へのグラデーション
    vec3 deepBlue = vec3(0.0, 0.1, 0.2);
    vec3 lightBlue = vec3(0.1, 0.5, 0.8);
    vec3 waterColor = mix(deepBlue, lightBlue, waves);

    // きらめき効果の生成
    float sparkleNoise = noise(vec2(uv.x * 40.0 + time, uv.y * 40.0 - time));
    float sparkle = pow(sparkleNoise, 15.0) * 2.0;

    // 波の高さに応じてきらめきを調整
    float waveHeight = sin(uv.x * 10.0 + time) * 0.5 + 0.5;
    sparkle *= waveHeight;

    // さらに小さな波紋を追加
    float ripples = sin(uv.x * 50.0 + time * 2.0) * sin(uv.y * 50.0 + time * 2.0) * 0.1;

    // 最終的な色の計算
    vec3 finalColor = waterColor;

    // きらめきの追加
    finalColor += vec3(sparkle) * vec3(0.8, 0.9, 1.0);

    // 波紋の効果を追加
    finalColor += ripples * vec3(0.2, 0.3, 0.4);

    // 画面上部を少し明るく
    finalColor += (1.0 - uv.y) * 0.1;

    // 最終出力
    fragColor = vec4(finalColor, 1.0);
}
